(7525763, 1202961, 173844, '<td valign="top">Love the assertively symmetric presentation offering the camouflaged rabbit.  The playful dissonance is very appealing.  Both modern and old-fashioned, straight-forward and tongue-in-cheek.  My personal favorite in the challenge.  If this is out of character, I encourage further exploration.</td>', 'Love the assertively symmetric presentation offering the camouflaged rabbit.  The playful dissonance is very appealing.  Both modern and old-fashioned, straight-forward and tongue-in-cheek.  My personal favorite in the challenge.  If this is out of character, I encourage further exploration.', '2017-07-27 16:25:28.000000', NULL, 1),
(7525764, 1203012, 173844, '<td valign="top">Enchanting, stylish scene.  Beautiful exposition of light.  Deeply inviting.  You got the knack.</td>', 'Enchanting, stylish scene.  Beautiful exposition of light.  Deeply inviting.  You got the knack.', '2017-07-27 16:28:31.000000', NULL, 1),
(7525765, 1202976, 173844, '<td valign="top">Sumptuously intimate image.  Hope the deer is okay, in which case this is more serene than any dawn lake or shut-eyed beachgoer.  Utterly pleasing.</td>', 'Sumptuously intimate image.  Hope the deer is okay, in which case this is more serene than any dawn lake or shut-eyed beachgoer.  Utterly pleasing.', '2017-07-27 16:39:22.000000', NULL, 1),
(7525766, 1202999, 173844, '<td valign="top">Extremely confident, fine image.  Elegant composition.  I admire the intuition that led you to offer the wide, kind of open expanse on the left.  Can''t see where this would be a stretch.</td>', 'Extremely confident, fine image.  Elegant composition.  I admire the intuition that led you to offer the wide, kind of open expanse on the left.  Can''t see where this would be a stretch.', '2017-07-27 16:45:55.000000', NULL, 1),
(7525767, 1202400, 173844, '<td valign="top">Fine street scene, active and empathetic.  Going black and white distills the mood and textures.  Excellent.</td>', 'Fine street scene, active and empathetic.  Going black and white distills the mood and textures.  Excellent.', '2017-07-27 16:50:57.000000', NULL, 1),
(7525768, 1203008, 173844, '<td valign="top">Terrific evocation of flight.  Sympathetic and personal --  not just any bird, it''s THIS one.  Beautiful blue background.</td>', 'Terrific evocation of flight.  Sympathetic and personal --  not just any bird, it''s THIS one.  Beautiful blue background.', '2017-07-27 16:54:35.000000', NULL, 1),
(7525769, 1202967, 173844, '<td valign="top">Startling, nicely done.  Gotta figure that "in character" tends towards kittens and dandelions.</td>', 'Startling, nicely done.  Gotta figure that "in character" tends towards kittens and dandelions.', '2017-07-27 16:57:08.000000', NULL, 1),
(7525770, 1202963, 173844, '<td valign="top">Wittily elliptic.  Impressive, beautifully handled presentation.  If this is out of character being in color rather than black and white, thus open new horizons.</td>', 'Wittily elliptic.  Impressive, beautifully handled presentation.  If this is out of character being in color rather than black and white, thus open new horizons.', '2017-07-27 17:10:26.000000', NULL, 1),
(7525771, 1202579, 173844, '<td valign="top">Kudos to radical experimentation.  This is done with exemplary panache.  Quite fine.</td>', 'Kudos to radical experimentation.  This is done with exemplary panache.  Quite fine.', '2017-07-27 17:12:53.000000', NULL, 1),
(7525772, 1202638, 173844, '<td valign="top">Diogenes in winter.  I see sincerity and determination on his face; his clarity of purpose is matched by the clarity of this depiction.  Well done.</td>', 'Diogenes in winter.  I see sincerity and determination on his face; his clarity of purpose is matched by the clarity of this depiction.  Well done.', '2017-07-27 17:16:27.000000', NULL, 1),
(7525773, 1202997, 173844, '<td valign="top">That he notices that he''s being photographed is the basis for his spontaneous expression, which gives the image its raison d''etre.  I also like the vertical expansiveness of the background.  Good stuff.</td>', 'That he notices that he''s being photographed is the basis for his spontaneous expression, which gives the image its raison d''etre.  I also like the vertical expansiveness of the background.  Good stuff.', '2017-07-27 17:21:35.000000', NULL, 1),
