(7526270, 1202979, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge well.<br/> <br/>This is a lovely mono nude made sensual by the lovely lighting. The dark shadows are for me what really gives the shape of your body its sensual appeal, lovely. But, youll have to count me in on the oil filter haters, like one of your commenters, initially I thought it was jpeg artefacts, it really detracts from an otherwise beautiful study. Im sure you would have finished much higher without it, other than that a really lovely study well executed Susan</td>', 'Hello from the critique club An appealing image that meets the challenge well. This is a lovely mono nude made sensual by the lovely lighting. The dark shadows are for me what really gives the shape of your body its sensual appeal, lovely. But, youll have to count me in on the oil filter haters, like one of your commenters, initially I thought it was jpeg artefacts, it really detracts from an otherwise beautiful study. Im sure you would have finished much higher without it, other than that a really lovely study well executed Susan', '2017-07-31 10:13:34.000000', NULL, 0),
(7526271, 1202638, 39880, '<td valign="top">Great shot.  Curious as to how you made the snow.</td>', 'Great shot.  Curious as to how you made the snow.', '2017-07-31 10:49:56.000000', NULL, 0),
(7526273, 1202465, 2333, '<td valign="top">Paul, this got my high score of the challenge. Love the composition. The whole mood is so ethereal. Well seen, well shot, well processed.</td>', 'Paul, this got my high score of the challenge. Love the composition. The whole mood is so ethereal. Well seen, well shot, well processed.', '2017-07-31 11:14:16.000000', NULL, 0),
(7526279, 1202465, 12611, '<td valign="top">Really nice. Not saying you should abandon your more prevalent styles, but God, man- shoot more like this!</td>', 'Really nice. Not saying you should abandon your more prevalent styles, but God, man- shoot more like this!', '2017-07-31 11:55:59.000000', NULL, 0),
(7526280, 1202400, 12611, '<td valign="top">This has the feel of mastery in that there are so many lovely moving parts. well done and congrats.</td>', 'This has the feel of mastery in that there are so many lovely moving parts. well done and congrats.', '2017-07-31 11:57:43.000000', NULL, 0);
